package com.campus.market.report;
import com.campus.market.product.ProductDetailCache;
import com.campus.market.auth.SessionService;
import com.campus.market.user.UserResponse;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.annotation.DirtiesContext;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;
import org.springframework.mock.web.MockHttpServletResponse;
import org.springframework.test.web.servlet.MockMvc;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
@SpringBootTest(properties={"spring.datasource.username=root","spring.datasource.password=","spring.flyway.enabled=true","market.product-cache.enabled=false","market.login-protection.enabled=false","market.orders.mq.enabled=false","market.orders.timeout-sweep-enabled=false","springdoc.api-docs.enabled=false"})
@AutoConfigureMockMvc
@DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
@EnabledIfEnvironmentVariable(named="LESSON85_DB_URL",matches="jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/campus_lesson85_verify\\?.*")
class ReportIntegrationTest {
    static Connection control;static String schema,url;
    @DynamicPropertySource static void database(DynamicPropertyRegistry registry)throws Exception {
        String base=System.getenv("LESSON85_DB_URL");control=DriverManager.getConnection(base,"root","");
        try(var s=control.createStatement();var r=s.executeQuery("SELECT @@datadir")){assertTrue(r.next());assertTrue(r.getString(1).contains("campus-lesson24-"));}
        schema="campus_lesson91_case_"+UUID.randomUUID().toString().replace("-","").substring(0,12);
        try(var s=control.createStatement()){s.execute("CREATE DATABASE "+schema+" CHARACTER SET utf8mb4");}
        url=base.replace("/campus_lesson85_verify?","/"+schema+"?");registry.add("spring.datasource.url",()->url);
    }
    @AfterAll static void removeSchema()throws Exception {if(control!=null)try{if(schema!=null&&schema.matches("campus_lesson91_case_[0-9a-f]{12}"))try(var s=control.createStatement()){s.execute("DROP DATABASE "+schema);}}finally{control.close();}}
    @Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;@Autowired SessionService sessions;
    @MockitoSpyBean ProductDetailCache cache;
    final JsonMapper json=JsonMapper.builder().build();String admin,seller,other,secondAdmin;
    @BeforeEach void fixtures(){
        for(String table:List.of("product_reports","product_moderation","product_moderation_events","order_timeout_outbox","order_events","market_orders","product_favorites","products","user_role_audit","user_role_grants","login_sessions","users"))jdbc.update("DELETE FROM "+table);
        jdbc.update("INSERT INTO users(id,username,password_hash,nickname) VALUES(101,'review_admin','not-used','审核员'),(102,'review_seller','not-used','卖家'),(103,'review_other','not-used','其他账号'),(104,'review_admin2','not-used','审核员乙')");
        jdbc.update("INSERT INTO user_role_grants(user_id,role_code) VALUES(101,'ADMIN'),(104,'ADMIN')");
        jdbc.update("INSERT INTO products(id,title,description,price_in_cents,seller_id,status,category_code) VALUES(201,'审核教材','整改前描述',3500,102,'ON_SALE','BOOK'),(202,'下架台灯','',100,102,'OFF_SHELF','DAILY'),(203,'已售出物品','',100,102,'SOLD','OTHER'),(204,'历史商品','',100,NULL,'ON_SALE','UNCLASSIFIED')");
        admin=token(101,"review_admin","审核员");seller=token(102,"review_seller","卖家");other=token(103,"review_other","其他账号");secondAdmin=token(104,"review_admin2","审核员乙");clearInvocations(cache);
    }
    String token(long id,String name,String nick){return "Bearer "+sessions.issueToken(new UserResponse(id,name,nick)).accessToken();}
    Map<String,Object> payload(String action,long version,String reason,String request){return Map.of("action",action,"version",version,"reason",reason,"requestId",request);}
    String key(){return UUID.randomUUID().toString();}
    org.springframework.mock.web.MockHttpServletResponse action(long id,String actor,Map<String,?> body)throws Exception {return mvc.perform(post("/api/admin/products/"+id+"/moderation/actions").header("Authorization",actor).contentType("application/json").content(json.writeValueAsString(body))).andReturn().getResponse();}
    JsonNode success(org.springframework.mock.web.MockHttpServletResponse r)throws Exception {assertEquals(200,r.getStatus(),r.getContentAsString());assertEquals("no-store",r.getHeader("Cache-Control"));return json.readTree(r.getContentAsByteArray());}
    JsonNode block(long id,long version)throws Exception {return success(action(id,admin,payload("BLOCK",version,"平台发现违规内容",key())));}
    JsonNode get(String path,String actor)throws Exception {var request=getRequest(path,actor);var response=mvc.perform(request).andReturn().getResponse();assertEquals(200,response.getStatus(),response.getContentAsString());if(path.startsWith("/api/admin")||path.contains("/moderation")||path.contains("/feed")||path.contains("/reports"))assertEquals("no-store",response.getHeader("Cache-Control"));return json.readTree(response.getContentAsByteArray());}
    org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder getRequest(String path,String actor){var request=org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(path);return actor==null?request:request.header("Authorization",actor);}
    int getStatus(String path,String actor)throws Exception {return mvc.perform(getRequest(path,actor)).andReturn().getResponse().getStatus();}
    org.springframework.mock.web.MockHttpServletResponse appeal(long id,String actor,long version,String reason,String request)throws Exception {return mvc.perform(post("/api/products/"+id+"/moderation/appeals").header("Authorization",actor).contentType("application/json").content(json.writeValueAsString(Map.of("version",version,"reason",reason,"requestId",request)))).andReturn().getResponse();}
    int sellerStatus(long id,String status,long version)throws Exception {return mvc.perform(put("/api/products/"+id+"/status").header("Authorization",seller).contentType("application/json").content(json.writeValueAsString(Map.of("status",status,"version",version)))).andReturn().getResponse().getStatus();}
    long version(long id){return jdbc.queryForObject("SELECT version FROM products WHERE id=?",Long.class,id);}
    int events(){return jdbc.queryForObject("SELECT COUNT(*) FROM product_moderation_events",Integer.class);}
    String state(long id){return jdbc.queryForObject("SELECT state FROM product_moderation WHERE product_id=?",String.class,id);}
    int createOrder()throws Exception {return mvc.perform(post("/api/products/201/orders").header("Authorization",other).contentType("application/json").content(json.writeValueAsString(Map.of("productVersion",0,"requestId",key())))).andReturn().getResponse().getStatus();}
    List<Integer> parallel(Callable<Integer> a,Callable<Integer> b)throws Exception {var pool=Executors.newFixedThreadPool(2);try{var x=pool.submit(a);var y=pool.submit(b);return List.of(x.get(15,TimeUnit.SECONDS),y.get(15,TimeUnit.SECONDS));}finally{pool.shutdownNow();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));}}

    MockHttpServletResponse submit(long product,String actor,String category,String reason,String request)throws Exception {var r=post("/api/products/"+product+"/reports").contentType("application/json").content(json.writeValueAsString(Map.of("category",category,"reason",reason,"requestId",request)));if(actor!=null)r.header("Authorization",actor);return mvc.perform(r).andReturn().getResponse();}
    long report()throws Exception {return created(submit(201,other,"MISLEADING","商品描述疑似不实",key())).path("ticket").path("id").asLong();}
    JsonNode created(MockHttpServletResponse r)throws Exception {assertEquals(201,r.getStatus(),r.getContentAsString());assertEquals("no-store",r.getHeader("Cache-Control"));return json.readTree(r.getContentAsByteArray());}
    MockHttpServletResponse resolve(long id,String actor,String action,String reason,long version,Long productVersion,String key)throws Exception {var data=new HashMap<String,Object>();data.put("action",action);data.put("reason",reason);data.put("version",version);data.put("productVersion",productVersion);data.put("requestId",key);var r=post("/api/admin/reports/"+id+"/resolve").contentType("application/json").content(json.writeValueAsString(data));if(actor!=null)r.header("Authorization",actor);return mvc.perform(r).andReturn().getResponse();}
    int count(){return jdbc.queryForObject("SELECT COUNT(*) FROM product_reports",Integer.class);}
    @Test void anonymousSubmissionRequiresLogin()throws Exception {assertEquals(401,submit(201,null,"OTHER","匿名举报",key()).getStatus());assertEquals(0,count());}
    @Test void reporterSnapshotIsImmutableAndNotActorControlled()throws Exception {var x=created(submit(201,other,"MISLEADING","描述不一致",key())).path("ticket");assertEquals("OPEN",x.path("status").asString());assertEquals("整改前描述",x.path("snapshot").path("description").asString());jdbc.update("UPDATE products SET description='后来修改' WHERE id=201");assertEquals("整改前描述",get("/api/reports/"+x.path("id").asLong(),other).path("snapshot").path("description").asString());assertEquals(103,jdbc.queryForObject("SELECT reporter_id FROM product_reports",Long.class));}
    @Test void ownProductForbiddenAndHiddenProductsUnavailable()throws Exception {assertEquals(403,submit(201,seller,"OTHER","举报自身",key()).getStatus());for(long id:List.of(202L,203L,999L))assertEquals(404,submit(id,other,"OTHER","不可见商品",key()).getStatus());}
    @Test void oldUnownedProductCanBeReported()throws Exception {assertEquals(201,submit(204,other,"OTHER","历史商品存在问题",key()).getStatus());}
    @Test void oneOpenReportPerReporterAndProduct()throws Exception {report();assertEquals(409,submit(201,other,"SPAM","重复举报",key()).getStatus());assertEquals(1,count());}
    @Test void sameSubmissionReplaysEvenAfterProductHidden()throws Exception {String key=key();long id=created(submit(201,other,"OTHER","举报说明",key)).path("ticket").path("id").asLong();block(201,0);var r=success(submit(201,other,"OTHER","举报说明",key));assertTrue(r.path("replayed").asBoolean());assertEquals(id,r.path("ticket").path("id").asLong());assertEquals(1,count());}
    @Test void changedPayloadCannotReuseKeyAcrossProducts()throws Exception {String key=key();created(submit(201,other,"OTHER","举报说明",key));assertEquals(409,submit(204,other,"OTHER","举报说明",key).getStatus());assertEquals(409,submit(201,other,"SPAM","举报说明",key).getStatus());assertEquals(409,submit(201,other,"OTHER","不同说明",key).getStatus());}
    @Test void categoryReasonUuidAndProductIdValidated()throws Exception {for(String category:List.of("BAD",""))assertEquals(400,submit(201,other,category,"说明正常",key()).getStatus());for(String reason:List.of("x"," ","x".repeat(301),"a\u0001b"))assertEquals(400,submit(201,other,"OTHER",reason,key()).getStatus());assertEquals(400,submit(201,other,"OTHER","正常说明","BAD").getStatus());assertEquals(400,submit(0,other,"OTHER","正常说明",key()).getStatus());}
    @Test void reporterCanOnlyReadOwnListAndDetail()throws Exception {long id=report();assertEquals(1,get("/api/reports",other).path("total").asInt());assertEquals(0,get("/api/reports",seller).path("total").asInt());assertEquals(404,getStatus("/api/reports/"+id,seller));assertEquals(404,getStatus("/api/reports/"+id,admin));assertEquals(401,getStatus("/api/reports/"+id,null));}
    @Test void sellerAndPublicDtosDoNotExposeReporterOrReason()throws Exception {long id=report();var own=get("/api/reports/"+id,other);assertFalse(own.has("reporterId"));assertFalse(own.has("resolvedBy"));assertFalse(get("/api/products/201",null).has("reporter"));assertEquals(404,getStatus("/api/reports/"+id,seller));}
    @Test void adminListAndDetailProtected()throws Exception {long id=report();for(String path:List.of("/api/admin/reports","/api/admin/reports/"+id)){assertEquals(401,getStatus(path,null));assertEquals(403,getStatus(path,seller));}assertEquals(103,get("/api/admin/reports/"+id,admin).path("reporter").path("id").asLong());assertEquals(1,get("/api/admin/reports?status=OPEN",admin).path("total").asInt());}
    @Test void paginationFiltersValidated()throws Exception {for(String query:List.of("page=0","size=21","status=BAD")){assertEquals(400,getStatus("/api/reports?"+query,other));assertEquals(400,getStatus("/api/admin/reports?"+query,admin));}}
    @Test void dismissDoesNotChangeProductOrCreateModerationEvent()throws Exception {long id=report();var x=success(resolve(id,admin,"DISMISS","证据不足，暂不处理",0,null,key())).path("ticket");assertEquals("DISMISSED",x.path("status").asString());assertEquals(1,x.path("version").asLong());assertEquals(0,version(201));assertEquals(0,events());assertEquals("ON_SALE",jdbc.queryForObject("SELECT status FROM products WHERE id=201",String.class));verify(cache,never()).evictAfterCommit(anyLong(),anyLong());}
    @Test void blockAndTicketResolveCommitTogether()throws Exception {long id=report();var x=success(resolve(id,admin,"BLOCK","核实违规，限制上架",0,0L,key())).path("ticket");assertEquals("ACTIONED",x.path("status").asString());assertTrue(x.path("moderationEventId").asLong()>0);assertEquals(1,events());assertEquals("BLOCKED",state(201));assertEquals(1,version(201));assertEquals(404,getStatus("/api/products/201",null));verify(cache).evictAfterCommit(201,0);}
    @Test void staleTicketAndProductVersionsConflict()throws Exception {long id=report();assertEquals(409,resolve(id,admin,"DISMISS","证据不足",1,null,key()).getStatus());assertEquals(409,resolve(id,admin,"BLOCK","核实违规",0,9L,key()).getStatus());assertEquals("OPEN",get("/api/reports/"+id,other).path("status").asString());assertEquals(0,events());}
    @Test void activeOrderAndSoldPreventBlockButAllowDismiss()throws Exception {long id=report();assertEquals(201,createOrder());assertEquals(409,resolve(id,admin,"BLOCK","存在违规",0,0L,key()).getStatus());assertEquals(200,resolve(id,admin,"DISMISS","已有订单转人工后续核查",0,null,key()).getStatus());}
    @Test void alreadyPlatformBlockedRejectsDuplicateBlock()throws Exception {long id=report();block(201,0);assertEquals(409,resolve(id,admin,"BLOCK","再次下架",0,1L,key()).getStatus());assertEquals(1,events());assertEquals("OPEN",get("/api/reports/"+id,other).path("status").asString());}
    @Test void successfulResolutionReplaysAndCannotBeChanged()throws Exception {long id=report();String key=key();success(resolve(id,admin,"BLOCK","核实违规",0,0L,key));var x=success(resolve(id,admin,"BLOCK","核实违规",0,0L,key));assertTrue(x.path("replayed").asBoolean());assertEquals(1,events());assertEquals(409,resolve(id,admin,"BLOCK","更改原因",0,0L,key).getStatus());assertEquals(409,resolve(id,secondAdmin,"DISMISS","另一个结果",0,null,key()).getStatus());}
    @Test void terminalResultPersistsAfterModerationReleased()throws Exception {long id=report();String key=key();success(resolve(id,admin,"BLOCK","核实违规",0,0L,key));success(action(201,admin,payload("RELEASE",1,"已整改解除",key())));assertTrue(success(resolve(id,admin,"BLOCK","核实违规",0,0L,key)).path("replayed").asBoolean());assertEquals("CLEAR",state(201));assertEquals(2,version(201));assertEquals(2,events());}
    @Test void reportAfterTerminalCreatesNewSnapshot()throws Exception {long id=report();success(resolve(id,admin,"DISMISS","原证据不足",0,null,key()));jdbc.update("UPDATE products SET description='新的内容' WHERE id=201");var x=created(submit(201,other,"SPAM","新的问题内容",key()));assertEquals("新的内容",x.path("ticket").path("snapshot").path("description").asString());assertEquals(2,count());}
    @Test void reportInsertFailureDoesNotChangeProduct()throws Exception {jdbc.execute("CREATE TRIGGER fail_report BEFORE INSERT ON product_reports FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='private fixture'");try{assertEquals(500,submit(201,other,"OTHER","正常说明",key()).getStatus());assertEquals(0,count());assertEquals(0,version(201));}finally{jdbc.execute("DROP TRIGGER fail_report");}}
    @Test void ticketFailureRollsBackModerationAndCacheCallback()throws Exception {long id=report();jdbc.execute("CREATE TRIGGER fail_resolution BEFORE UPDATE ON product_reports FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='private fixture'");try{assertEquals(500,resolve(id,admin,"BLOCK","核实违规",0,0L,key()).getStatus());assertEquals(0,events());assertEquals(0,version(201));assertEquals("OPEN",get("/api/reports/"+id,other).path("status").asString());}finally{jdbc.execute("DROP TRIGGER fail_resolution");}}
    @Test void moderationFailureLeavesTicketOpen()throws Exception {long id=report();jdbc.execute("CREATE TRIGGER fail_report_event BEFORE INSERT ON product_moderation_events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='private fixture'");try{assertEquals(500,resolve(id,admin,"BLOCK","核实违规",0,0L,key()).getStatus());assertEquals(0,events());assertEquals(0,version(201));assertEquals("OPEN",get("/api/reports/"+id,other).path("status").asString());}finally{jdbc.execute("DROP TRIGGER fail_report_event");}}
    @Test void concurrentSameSubmissionCreatesOnlyOneTicket()throws Exception {String key=key();var codes=parallel(()->submit(201,other,"OTHER","并发举报",key).getStatus(),()->submit(201,other,"OTHER","并发举报",key).getStatus());assertEquals(Set.of(200,201),new HashSet<>(codes));assertEquals(1,count());}
    @Test void concurrentDistinctSubmissionsPreserveOnePending()throws Exception {var codes=parallel(()->submit(201,other,"OTHER","并发举报甲",key()).getStatus(),()->submit(201,other,"OTHER","并发举报乙",key()).getStatus());assertEquals(Set.of(201,409),new HashSet<>(codes));assertEquals(1,count());}
    @Test void competingAdminsResolveOnlyOnce()throws Exception {long id=report();var codes=parallel(()->resolve(id,admin,"BLOCK","核实违规",0,0L,key()).getStatus(),()->resolve(id,secondAdmin,"DISMISS","证据不足",0,null,key()).getStatus());assertEquals(Set.of(200,409),new HashSet<>(codes));assertTrue(events()<=1);assertEquals(1,get("/api/reports/"+id,other).path("version").asLong());}
    @Test void revokedAdminCannotReplayOrRead()throws Exception {long id=report();String key=key();success(resolve(id,admin,"DISMISS","证据不足",0,null,key));jdbc.update("DELETE FROM user_role_grants WHERE user_id=101");assertEquals(403,resolve(id,admin,"DISMISS","证据不足",0,null,key).getStatus());assertEquals(403,getStatus("/api/admin/reports/"+id,admin));}
    @Test void resolutionKeyCannotBeSharedAcrossTickets()throws Exception {long a=report();long b=created(submit(204,other,"OTHER","另一个问题商品",key())).path("ticket").path("id").asLong();String key=key();success(resolve(a,admin,"DISMISS","证据不足",0,null,key));assertEquals(409,resolve(b,admin,"BLOCK","核实违规",0,0L,key).getStatus());assertEquals(0,events());assertEquals(0,version(204));assertEquals("OPEN",get("/api/reports/"+b,other).path("status").asString());}
    @Test void reusedModerationKeyDoesNotResolveAnotherTicket()throws Exception {String key=key();success(action(204,admin,payload("BLOCK",0,"核实违规",key)));long id=report();assertEquals(409,resolve(id,admin,"BLOCK","核实违规",0,0L,key).getStatus());assertEquals("OPEN",get("/api/reports/"+id,other).path("status").asString());assertEquals(0,version(201));}
    @Test void malformedAndUnknownDecisionRefused()throws Exception {long id=report();assertEquals(400,resolve(id,admin,"DELETE","非法动作",0,null,key()).getStatus());assertEquals(400,resolve(id,admin,"DISMISS","正常原因",0,0L,key()).getStatus());assertEquals(400,resolve(id,admin,"BLOCK","正常原因",0,null,key()).getStatus());assertEquals(404,resolve(999,admin,"DISMISS","正常原因",0,null,key()).getStatus());assertEquals(403,resolve(id,other,"DISMISS","越权处理",0,null,key()).getStatus());}
    @Test void listsAreStableAndBounded()throws Exception {for(int n=0;n<5;n++){long id=report();success(resolve(id,admin,"DISMISS","证据不足",0,null,key()));}var a=get("/api/reports?size=2&page=1",other);var b=get("/api/reports?size=2&page=2",other);assertEquals(5,a.path("total").asInt());assertEquals(2,a.path("records").size());assertTrue(a.path("records").get(1).path("id").asLong()>b.path("records").get(0).path("id").asLong());}
    @Test void databaseRejectsPartialTerminalState()throws Exception {long id=report();assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE product_reports SET status='ACTIONED',version=1 WHERE id=?",id));assertEquals("OPEN",get("/api/reports/"+id,other).path("status").asString());}
}
